/**
 * Voxel.io Arena PVP Game Mode
 * Fast-paced voxel combat arena with kits, combos, knockback, and leaderboards.
 */

import { GameModeBase } from './GameModeBase.js';

export class ArenaPvpMode extends GameModeBase {
  constructor(options = {}) {
    super('arena_pvp', 'Arena PVP', options);

    this.kits = {
      knight: {
        name: 'Knight',
        desc: 'Balanced warrior with Iron Armor and Sharp Diamond Sword',
        weapon: 'Diamond Sword',
        damage: 7,
        armor: 'iron',
        items: [{ id: 'golden_apple', count: 1 }],
      },
      archer: {
        name: 'Archer',
        desc: 'Ranged specialist with Bow, 64 Arrows, and Speed Boost',
        weapon: 'Bow',
        damage: 4,
        arrows: 64,
        armor: 'leather',
        speedMultiplier: 1.25,
      },
      juggernaut: {
        name: 'Juggernaut',
        desc: 'Heavy tank with Diamond Armor and Knockback Club',
        weapon: 'Knockback Club',
        damage: 5,
        knockbackMult: 2.0,
        armor: 'diamond',
        hp: 30,
      },
      berserker: {
        name: 'Berserker',
        desc: 'High-risk high-reward berserker with Battleaxe and Golden Apples',
        weapon: 'Iron Axe',
        damage: 9,
        armor: 'chainmail',
        items: [{ id: 'golden_apple', count: 3 }],
      },
    };

    this.selectedKit = options.kit || 'knight';
    this.killCount = 0;
    this.deathCount = 0;
    this.currentStreak = 0;
    this.bestStreak = 0;
    this.leaderboard = new Map();
    this.combos = new Map();
  }

  onStart() {
    this.leaderboard.set('local_player', { name: 'You', kills: 0, deaths: 0 });

    if (this.engine?.world) {
      this.generateArenaMap();
    }

    // Spawn 3 AI gladiators
    const botKits = ['archer', 'berserker', 'juggernaut'];
    botKits.forEach((kit, i) => {
      const angle = (i * Math.PI * 2) / 3;
      const radius = 18;
      const bot = {
        id: `gladiator_${i + 1}`,
        name: `Gladiator_${i + 1}`,
        kit: kit,
        pos: [Math.cos(angle) * radius, 65, Math.sin(angle) * radius],
        hp: 20,
        kills: 0,
        actionTimer: 0,
      };
      this.bots.push(bot);
      this.leaderboard.set(bot.id, { name: bot.name, kills: 0, deaths: 0 });
    });
  }

  generateArenaMap() {
    const world = this.engine.world;
    if (!world?.setBlock) return;

    // Arena Floor (circle radius 24 at y=64)
    for (let x = -26; x <= 26; x++) {
      for (let z = -26; z <= 26; z++) {
        const dist = Math.hypot(x, z);
        if (dist <= 24) {
          world.setBlock(x, 64, z, 1); // stone
          if (dist > 22) {
            // Perimeter boundary wall
            for (let y = 65; y <= 68; y++) world.setBlock(x, y, z, 49); // obsidian
          }
        }
      }
    }

    // Central Pillar and jumping platforms
    for (let y = 65; y <= 69; y++) {
      world.setBlock(0, y, 0, 98); // stone brick
    }
    // 4 Corner Obstacles
    const corners = [[-12, -12], [12, -12], [-12, 12], [12, 12]];
    corners.forEach(([cx, cz]) => {
      for (let y = 65; y <= 67; y++) {
        for (let dx = -1; dx <= 1; dx++) {
          for (let dz = -1; dz <= 1; dz++) {
            world.setBlock(cx + dx, y, cz + dz, 98);
          }
        }
      }
    });
  }

  onUpdate(dt) {
    // Tick bots AI combat
    for (const bot of this.bots) {
      bot.actionTimer += dt;
      if (bot.actionTimer > 1.2) {
        bot.actionTimer = 0;
        this.stepBotCombat(bot, dt);
      }
    }
  }

  stepBotCombat(bot, dt) {
    if (bot.hp <= 0) return;
    const [px, py, pz] = this.engine?.localPlayer?.position || [0, 65, 0];
    const dist = Math.hypot(px - bot.pos[0], pz - bot.pos[2]);

    if (dist < 3.0) {
      // Attack player
      const kitData = this.kits[bot.kit];
      const dmg = kitData.damage || 4;
      this.engine?.localPlayer?.takeDamage?.(dmg, bot.id);
      this.ui?.showNotification?.(`${bot.name} dealt ${dmg} damage!`, 'combat');
    } else if (dist < 20.0) {
      // Approach player
      const dirX = (px - bot.pos[0]) / dist;
      const dirZ = (pz - bot.pos[2]) / dist;
      bot.pos[0] += dirX * 4.0;
      bot.pos[2] += dirZ * 4.0;
    }
  }

  onPlayerAttack(attackerId, targetId, weapon) {
    const kit = this.kits[this.selectedKit];
    let damage = kit.damage || 5;

    // Check combo
    let streak = (this.combos.get(attackerId) || 0) + 1;
    this.combos.set(attackerId, streak);
    if (streak > 2) damage += 1; // Combo bonus damage

    // Check if target is a bot
    const bot = this.bots.find((b) => b.id === targetId);
    if (bot) {
      bot.hp -= damage;
      if (bot.hp <= 0) {
        this.onGladiatorKilled('local_player', bot);
      }
    }

    return {
      damage,
      combo: streak,
      knockback: [0, 1.5, kit.knockbackMult ? kit.knockbackMult * 4 : 3],
    };
  }

  onGladiatorKilled(killerId, bot) {
    this.killCount++;
    this.currentStreak++;
    if (this.currentStreak > this.bestStreak) this.bestStreak = this.currentStreak;

    const killerStats = this.leaderboard.get(killerId);
    if (killerStats) killerStats.kills++;

    const msg = `You defeated ${bot.name}! (Streak: ${this.currentStreak})`;
    this.ui?.showNotification?.(msg, 'success');

    // Respawn bot after 3 seconds
    setTimeout(() => {
      bot.hp = 20;
      bot.pos = [Math.random() * 20 - 10, 65, Math.random() * 20 - 10];
    }, 3000);
  }

  getHudData() {
    return {
      mode: 'Arena PVP',
      state: this.state,
      kit: this.kits[this.selectedKit].name,
      kills: this.killCount,
      deaths: this.deathCount,
      streak: this.currentStreak,
      bestStreak: this.bestStreak,
      leaderboard: Array.from(this.leaderboard.values()),
    };
  }
}
