/**
 * Voxel.io Skywars & Creative Game Mode
 * Floating sky islands with chest loot & void death (Skywars), and infinite flying voxel builder (Creative).
 */

import { GameModeBase } from './GameModeBase.js';

export class SkywarsCreativeMode extends GameModeBase {
  constructor(options = {}) {
    super('skywars_creative', options.subMode === 'creative' ? 'Creative Sandbox' : 'Skywars', options);

    this.subMode = options.subMode || 'skywars'; // 'skywars' | 'creative'

    // Skywars specific state
    this.islands = [];
    this.chests = [];
    this.aliveCount = 8;
    this.voidLevel = 10;
    this.borderShrinkTimer = 180; // 3 minutes to sudden death

    // Creative specific state
    this.isFlying = false;
    this.selectedBlock = 1; // Stone
    this.creativeBlocks = [
      { id: 1, name: 'Stone' },
      { id: 2, name: 'Grass Block' },
      { id: 3, name: 'Dirt' },
      { id: 4, name: 'Cobblestone' },
      { id: 5, name: 'Oak Wood' },
      { id: 20, name: 'Glass' },
      { id: 35, name: 'White Wool' },
      { id: 41, name: 'Gold Block' },
      { id: 46, name: 'TNT' },
      { id: 49, name: 'Obsidian' },
      { id: 57, name: 'Diamond Block' },
      { id: 89, name: 'Glowstone' },
      { id: 98, name: 'Stone Bricks' },
    ];
  }

  onStart() {
    if (this.subMode === 'skywars') {
      this.initSkywars();
    } else {
      this.initCreative();
    }
  }

  initSkywars() {
    this.aliveCount = 8;
    this.borderShrinkTimer = 180;

    if (this.engine?.world) {
      this.generateSkyIslands();
    }

    // Spawn 7 AI Skywars combatants
    for (let i = 1; i <= 7; i++) {
      const angle = (i * Math.PI * 2) / 8;
      const radius = 35;
      const bot = {
        id: `sky_player_${i}`,
        name: `Skywarrior_${i}`,
        pos: [Math.cos(angle) * radius, 70, Math.sin(angle) * radius],
        hp: 20,
        blocks: 32,
        pearls: 1,
        state: 'LOOT', // 'LOOT' | 'BRIDGE' | 'FIGHT'
      };
      this.bots.push(bot);
    }
  }

  generateSkyIslands() {
    const world = this.engine.world;
    if (!world?.setBlock) return;

    // Center Mega Island at [0, 68, 0]
    for (let x = -6; x <= 6; x++) {
      for (let z = -6; z <= 6; z++) {
        const d = Math.hypot(x, z);
        if (d <= 6) {
          world.setBlock(x, 68, z, 1);
          world.setBlock(x, 69, z, 2);
        }
      }
    }
    // Mega Chest at center
    world.setBlock(0, 70, 0, 54);

    // 8 Player Islands in a circle
    for (let i = 0; i < 8; i++) {
      const angle = (i * Math.PI * 2) / 8;
      const cx = Math.round(Math.cos(angle) * 35);
      const cz = Math.round(Math.sin(angle) * 35);

      for (let x = cx - 3; x <= cx + 3; x++) {
        for (let z = cz - 3; z <= cz + 3; z++) {
          world.setBlock(x, 69, z, 1);
          world.setBlock(x, 70, z, 2);
        }
      }
      // Island Chest
      world.setBlock(cx, 71, cz, 54);
    }
  }

  initCreative() {
    this.isFlying = true;
    this.ui?.showNotification?.('🎨 Creative Mode: Press [F] to toggle fly, [B] for Block Palette!', 'info');

    if (this.engine?.world) {
      // Flat creative canvas 60x60
      const world = this.engine.world;
      for (let x = -30; x <= 30; x++) {
        for (let z = -30; z <= 30; z++) {
          world.setBlock?.(x, 60, z, 2); // green grass
        }
      }
    }
  }

  onUpdate(dt) {
    if (this.subMode === 'skywars') {
      this.borderShrinkTimer = Math.max(0, this.borderShrinkTimer - dt);

      // Check void falls for player
      const p = this.engine?.localPlayer?.position || [0, 70, 0];
      if (p[1] < this.voidLevel) {
        this.engine?.localPlayer?.takeDamage?.(100, 'Void');
        this.ui?.showNotification?.('You fell into the void!', 'danger');
      }

      // Tick bots
      for (const bot of this.bots) {
        if (bot.hp > 0 && bot.pos[1] < this.voidLevel) {
          bot.hp = 0;
          this.aliveCount = Math.max(1, this.aliveCount - 1);
          this.ui?.showNotification?.(`${bot.name} fell into the void!`, 'info');
        }
      }
    }
  }

  toggleFly() {
    this.isFlying = !this.isFlying;
    this.ui?.showNotification?.(this.isFlying ? 'Flight Enabled 🕊️' : 'Flight Disabled', 'info');
  }

  selectBlock(blockId) {
    this.selectedBlock = blockId;
    const b = this.creativeBlocks.find((x) => x.id === blockId);
    this.ui?.showNotification?.(`Selected: ${b ? b.name : 'Block #' + blockId}`, 'info');
  }

  getHudData() {
    if (this.subMode === 'skywars') {
      return {
        mode: 'Skywars',
        state: this.state,
        alive: this.aliveCount,
        timer: Math.round(this.borderShrinkTimer),
      };
    }
    return {
      mode: 'Creative',
      state: this.state,
      flying: this.isFlying,
      selectedBlock: this.selectedBlock,
    };
  }
}
