/**
 * Voxel.io Real 3D WebGL Voxel Engine
 * High-performance voxel rendering with Three.js, chunk meshing, player physics,
 * sound/particle effects, and code-api compatibility.
 */

import * as THREE from 'three';
import { VoxelWorld, BLOCK_TYPES } from './VoxelWorld.js';
import { Physics } from './Physics.js';
import { SoundManager } from './SoundManager.js';
import { ParticleSystem } from './ParticleSystem.js';

export class VoxelEngineFacade {
  constructor(canvasContainer) {
    this.container = canvasContainer;
    this.canvas = null;
    this.scene = null;
    this.camera = null;
    this.renderer = null;
    this.world = null;
    this.physics = null;
    this.soundManager = null;
    this.particleSystem = null;

    this.localPlayer = null;
    this.activeMode = null;
    this.rafId = null;
    this.lastTime = performance.now();
    this.blockData = new Map();
    this.listeners = new Map();
    this.isPaused = false;

    // Input state
    this.keys = {};
    this.mouse = { x: 0, y: 0, isLocked: false };
    this.selectedHotbarSlot = 0;

    this.initWebGL();
    this.initLocalPlayer();
    this.initCodeApi();
    this.initControls();
  }

  initWebGL() {
    // 1. Canvas setup
    this.canvas = document.getElementById('game-canvas');
    if (!this.canvas) {
      this.canvas = document.createElement('canvas');
      this.canvas.id = 'game-canvas';
      this.canvas.className = 'game-canvas';
      this.canvas.style.position = 'absolute';
      this.canvas.style.top = '0';
      this.canvas.style.left = '0';
      this.canvas.style.width = '100%';
      this.canvas.style.height = '100%';
      this.canvas.style.zIndex = '1';
      this.container.appendChild(this.canvas);
    }

    // 2. Three.js Scene & Sky
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x87CEEB); // Bloxd day sky blue
    this.scene.fog = new THREE.FogExp2(0x87CEEB, 0.008);

    // 3. Perspective Camera
    const width = window.innerWidth || 800;
    const height = window.innerHeight || 600;
    this.camera = new THREE.PerspectiveCamera(75, width / height, 0.05, 500);
    this.camera.position.set(0, 66, 0);
    this.scene.add(this.camera);

    // 4. Directional Sun Light & Ambient Light
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.7);
    this.scene.add(ambientLight);

    const sunLight = new THREE.DirectionalLight(0xfff5e6, 0.85);
    sunLight.position.set(50, 100, 50);
    this.scene.add(sunLight);

    // 5. WebGL Renderer
    try {
      this.renderer = new THREE.WebGLRenderer({
        canvas: this.canvas,
        antialias: true,
        powerPreference: 'high-performance',
      });
      this.renderer.setSize(width, height);
      this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    } catch (e) {
      console.warn('[VoxelEngine] Fallback mock renderer (headless):', e);
      this.renderer = {
        setSize: () => {},
        setPixelRatio: () => {},
        render: () => {},
        domElement: this.canvas,
      };
    }

    // 6. Subsystems: Voxel World, Physics, Audio, Particles
    this.world = new VoxelWorld(this.scene);
    this.physics = new Physics(this.world);
    this.soundManager = new SoundManager();
    this.particleSystem = new ParticleSystem(this.scene);

    window.addEventListener('resize', () => this.onResize());
  }

  onResize() {
    if (!this.camera || !this.renderer) return;
    const width = window.innerWidth || 800;
    const height = window.innerHeight || 600;
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(width, height);
  }

  initLocalPlayer() {
    this.localPlayer = {
      id: 'local_player',
      name: 'VoxelPlayer',
      position: [0, 66, 0],
      velocity: [0, 0, 0],
      yaw: 0,
      pitch: 0,
      hp: 20,
      maxHp: 20,
      inventory: {
        iron: 0,
        gold: 0,
        diamond: 0,
        emerald: 0,
        items: new Map(),
      },
      addInventory: (type, count) => {
        if (this.localPlayer.inventory[type] !== undefined) {
          this.localPlayer.inventory[type] += count;
        } else {
          const cur = this.localPlayer.inventory.items.get(type) || 0;
          this.localPlayer.inventory.items.set(type, cur + count);
        }
      },
      takeDamage: (amount, sourceId) => {
        this.localPlayer.hp = Math.max(0, this.localPlayer.hp - amount);
        this.soundManager?.playHurt?.(this.localPlayer.position);
        this.emit('player_damage', { amount, sourceId, hp: this.localPlayer.hp });
        if (this.localPlayer.hp === 0) {
          this.emit('player_death', { playerId: 'local_player', killerId: sourceId });
        }
      },
      heal: (amount) => {
        this.localPlayer.hp = Math.min(this.localPlayer.maxHp, this.localPlayer.hp + amount);
      },
      respawn: (spawnPos) => {
        const target = spawnPos ? [...spawnPos] : [0, 66, 0];
        this.localPlayer.position = target;
        this.localPlayer.velocity = [0, 0, 0];
        this.localPlayer.hp = this.localPlayer.maxHp;
        if (this.camera) {
          this.camera.position.set(target[0], target[1] + 1.6, target[2]);
        }
      },
    };
  }

  initControls() {
    window.addEventListener('keydown', (e) => {
      this.keys[e.code] = true;
      if (e.key >= '1' && e.key <= '9') {
        this.selectedHotbarSlot = parseInt(e.key) - 1;
        this.emit('hotbar_slot_changed', this.selectedHotbarSlot);
      }
    });

    window.addEventListener('keyup', (e) => {
      this.keys[e.code] = false;
    });

    // Pointer Lock
    if (this.canvas) {
      this.canvas.addEventListener('click', () => {
        if (document.pointerLockElement !== this.canvas) {
          this.canvas.requestPointerLock?.();
        }
      });
    }

    document.addEventListener('pointerlockchange', () => {
      this.mouse.isLocked = document.pointerLockElement === this.canvas;
    });

    document.addEventListener('mousemove', (e) => {
      if (!this.mouse.isLocked) return;
      const sensitivity = 0.0022;
      this.localPlayer.yaw -= e.movementX * sensitivity;
      this.localPlayer.pitch = Math.max(
        -Math.PI / 2.05,
        Math.min(Math.PI / 2.05, this.localPlayer.pitch - e.movementY * sensitivity)
      );

      if (this.camera) {
        this.camera.rotation.order = 'YXZ';
        this.camera.rotation.y = this.localPlayer.yaw;
        this.camera.rotation.x = this.localPlayer.pitch;
      }
    });

    // Mouse block interactions
    window.addEventListener('mousedown', (e) => {
      if (!this.mouse.isLocked || !this.world) return;
      if (e.button === 0) {
        // Left click: mine block
        this.performRaycastAction('break');
      } else if (e.button === 2) {
        // Right click: place block
        this.performRaycastAction('place');
      }
    });
  }

  performRaycastAction(action) {
    if (!this.camera || !this.world) return;
    const origin = [this.camera.position.x, this.camera.position.y, this.camera.position.z];
    const dir = new THREE.Vector3();
    this.camera.getWorldDirection(dir);
    const direction = [dir.x, dir.y, dir.z];

    const hit = this.physics.raycast(origin, direction, 5.5);
    if (!hit) return;

    if (action === 'break') {
      const blockId = this.world.getBlock(hit.voxel[0], hit.voxel[1], hit.voxel[2]);
      if (blockId !== BLOCK_TYPES.BEDROCK) {
        this.world.setBlock(hit.voxel[0], hit.voxel[1], hit.voxel[2], BLOCK_TYPES.AIR);
        this.soundManager.playDig(blockId, hit.voxel);
        this.particleSystem.spawnBreakParticles(hit.voxel, blockId);
        this.emit('block_break', { pos: hit.voxel, blockType: blockId });
      }
    } else if (action === 'place') {
      const targetPos = [
        hit.voxel[0] + hit.normal[0],
        hit.voxel[1] + hit.normal[1],
        hit.voxel[2] + hit.normal[2],
      ];
      const placeType = BLOCK_TYPES.WHITE_WOOL;
      this.world.setBlock(targetPos[0], targetPos[1], targetPos[2], placeType);
      this.soundManager.playStep(placeType, targetPos);
      this.emit('block_place', { pos: targetPos, blockType: placeType });
    }
  }

  initCodeApi() {
    const self = this;
    const api = {
      getBlock: (x, y, z) => self.world?.getBlock?.(x, y, z) || 0,
      setBlock: (x, y, z, id) => self.world?.setBlock?.(x, y, z, id),
      getBlockData: (x, y, z) => self.blockData.get(`${x},${y},${z}`) || null,
      setBlockData: (x, y, z, data) => self.blockData.set(`${x},${y},${z}`, data),
      setPosition: (playerId, x, y, z) => {
        if (playerId === 'local_player') {
          self.localPlayer.position = [x, y, z];
          if (self.camera) self.camera.position.set(x, y + 1.6, z);
        }
      },
      getPosition: (playerId) => {
        return playerId === 'local_player' ? self.localPlayer.position : [0, 66, 0];
      },
      setClientOption: (playerId, opt, val) => {},
      setMaxPlayers: (soft, hard) => {},
      setItemSlot: (playerId, slot, item, count) => {
        if (playerId === 'local_player') self.localPlayer.addInventory(item, count);
      },
      broadcastMessage: (msg, opts) => {
        console.log(`[Voxel.io Chat]`, msg);
      },
      playAudio: (soundName, opts) => {},
      onCreateVoxelMeshEntity: (type, pos, opts) => {
        return { id: `mesh_${Date.now()}`, type, pos };
      },
      onCreateBloxdMeshEntity: (type, pos, opts) => {
        return api.onCreateVoxelMeshEntity(type, pos, opts);
      },
      registerCustomBlock: (name, def) => {},
    };

    if (typeof globalThis !== 'undefined') {
      globalThis.api = api;
      globalThis.JIS = 'Voxel.io';
    }
  }

  on(event, fn) {
    if (!this.listeners.has(event)) this.listeners.set(event, []);
    this.listeners.get(event).push(fn);
  }

  emit(event, data) {
    const list = this.listeners.get(event);
    if (list) {
      for (const fn of list) fn(data);
    }
  }

  setGameMode(modeInstance) {
    if (this.activeMode) {
      this.activeMode.destroy();
    }
    this.activeMode = modeInstance;
    this.activeMode.init(this, null, null);
    this.activeMode.start();
  }

  updatePlayerPhysics(dt) {
    if (!this.localPlayer || !this.camera) return;

    // Movement vector from keys
    const forward = (this.keys['KeyW'] ? 1 : 0) - (this.keys['KeyS'] ? 1 : 0);
    const strafe = (this.keys['KeyD'] ? 1 : 0) - (this.keys['KeyA'] ? 1 : 0);
    const speed = this.keys['ControlLeft'] || this.keys['ShiftLeft'] ? 8.5 : 5.2;

    const yaw = this.localPlayer.yaw;
    const sin = Math.sin(yaw);
    const cos = Math.cos(yaw);

    const moveX = (forward * -sin + strafe * cos) * speed;
    const moveZ = (forward * -cos + strafe * -sin) * speed;

    this.localPlayer.velocity[0] = moveX;
    this.localPlayer.velocity[2] = moveZ;

    // Jump
    if (this.keys['Space'] && this.localPlayer.onGround) {
      this.localPlayer.velocity[1] = 8.2;
      this.localPlayer.onGround = false;
    }

    // Step physics
    if (this.physics?.updateEntity) {
      this.physics.updateEntity(this.localPlayer, dt);
    } else {
      this.localPlayer.position[0] += this.localPlayer.velocity[0] * dt;
      this.localPlayer.position[1] += this.localPlayer.velocity[1] * dt;
      this.localPlayer.position[2] += this.localPlayer.velocity[2] * dt;
    }

    // Bind camera to player eye height
    this.camera.position.set(
      this.localPlayer.position[0],
      this.localPlayer.position[1] + 1.6,
      this.localPlayer.position[2]
    );
  }

  startLoop() {
    const loop = (time) => {
      const dt = Math.min((time - this.lastTime) / 1000, 0.1);
      this.lastTime = time;

      if (!this.isPaused) {
        this.updatePlayerPhysics(dt);

        if (this.activeMode) {
          this.activeMode.update(dt);
        }

        if (this.particleSystem?.update) {
          this.particleSystem.update(dt);
        }

        if (this.renderer && this.scene && this.camera) {
          this.renderer.render(this.scene, this.camera);
        }
      }

      this.rafId = requestAnimationFrame(loop);
    };

    this.rafId = requestAnimationFrame(loop);
  }

  stopLoop() {
    if (this.rafId) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
  }
}
