export function getGameById(id) {
  return GAME_ROSTER.find((g) => g.id === id) || null;
}

export function createGameInstance(id, options = {}) {
  const game = getGameById(id);
  if (!game) {
    throw new Error(`[Voxel.io] Unknown game mode id: ${id}`);
  }
  return game.factory(options);
}
