/**
 * Voxel.io Doors Game Mode
 * Procedural horror hotel rooms, keys, closets, flickering lights, and entity encounters (Rush, Screech, Ambush).
 */

import { GameModeBase } from './GameModeBase.js';

export class DoorsMode extends GameModeBase {
  constructor(options = {}) {
    super('doors', 'Doors', options);

    this.currentRoom = 1;
    this.maxRooms = 100;
    this.gold = 0;
    this.hasKey = false;
    this.isHidingInCloset = false;
    this.lightFlickerTimer = 0;
    this.lightsFlickering = false;
    this.rushActive = false;
    this.rushDistance = 0;
    this.flashlightBattery = 100;
    this.inventory = ['Lighter'];

    this.roomData = new Map();
  }

  onStart() {
    this.currentRoom = 1;
    this.gold = 0;
    this.hasKey = false;
    this.isHidingInCloset = false;

    if (this.engine?.world) {
      this.generateRoom(this.currentRoom);
    }
  }

  generateRoom(roomNum) {
    const world = this.engine.world;
    if (!world?.setBlock) return;

    const zStart = (roomNum - 1) * 20;
    const zEnd = zStart + 20;

    // Build 7x20 room corridor (width -3 to 3, height 64 to 68)
    for (let x = -4; x <= 4; x++) {
      for (let z = zStart; z <= zEnd; z++) {
        // Floor & Ceiling
        world.setBlock(x, 64, z, 5); // wood planks floor
        world.setBlock(x, 68, z, 5); // wood ceiling

        // Side Walls
        world.setBlock(-4, 65, z, 43); // wall
        world.setBlock(-4, 66, z, 43);
        world.setBlock(-4, 67, z, 43);

        world.setBlock(4, 65, z, 43);
        world.setBlock(4, 66, z, 43);
        world.setBlock(4, 67, z, 43);
      }
    }

    // Door wall at end of room
    for (let x = -4; x <= 4; x++) {
      for (let y = 65; y <= 67; y++) {
        if (x === 0 && (y === 65 || y === 66)) {
          world.setBlock(x, y, zEnd, 64); // Door frame
        } else {
          world.setBlock(x, y, zEnd, 43);
        }
      }
    }

    // Closet at x = -3, z = zStart + 10
    world.setBlock(-3, 65, zStart + 10, 17); // wood pillar closet

    // Decide room properties
    const isLocked = roomNum % 3 === 0;
    const isDark = roomNum > 5 && Math.random() < 0.3;
    this.hasKey = !isLocked;

    this.roomData.set(roomNum, {
      locked: isLocked,
      dark: isDark,
      keyFound: !isLocked,
      zStart,
      zEnd,
    });

    if (isLocked) {
      this.ui?.showNotification?.(`Room ${roomNum} is LOCKED! Find the key in the drawers.`, 'info');
    }
  }

  onUpdate(dt) {
    if (this.flashlightBattery > 0) {
      this.flashlightBattery = Math.max(0, this.flashlightBattery - dt * 0.1);
    }

    // Random light flicker event (Rush warning)
    this.lightFlickerTimer += dt;
    if (this.currentRoom >= 5 && !this.rushActive && this.lightFlickerTimer > 25) {
      this.lightFlickerTimer = 0;
      if (Math.random() < 0.4) {
        this.triggerRushEvent();
      }
    }

    // Update Rush event progress
    if (this.rushActive) {
      this.rushDistance += dt * 30; // 30 blocks per sec
      if (this.rushDistance >= 25) {
        // Rush arrives at player position!
        this.rushActive = false;
        if (!this.isHidingInCloset) {
          // Player failed to hide in closet!
          this.engine?.localPlayer?.takeDamage?.(100, 'Rush');
          this.ui?.showNotification?.('You died to Rush! Next time, hide in a closet when lights flicker!', 'danger');
        } else {
          this.ui?.showNotification?.('Rush has passed safely!', 'success');
        }
      }
    }
  }

  triggerRushEvent() {
    this.rushActive = true;
    this.rushDistance = 0;
    this.lightsFlickering = true;
    this.ui?.showNotification?.('⚠️ The lights are flickering... HIDE IN A CLOSET!', 'warning');

    setTimeout(() => {
      this.lightsFlickering = false;
    }, 4000);
  }

  toggleHideInCloset() {
    this.isHidingInCloset = !this.isHidingInCloset;
    const msg = this.isHidingInCloset ? 'Hiding inside closet...' : 'Stepped out of closet.';
    this.ui?.showNotification?.(msg, 'info');
  }

  collectKey() {
    this.hasKey = true;
    const cur = this.roomData.get(this.currentRoom);
    if (cur) cur.keyFound = true;
    this.ui?.showNotification?.('🔑 You found the Room Key!', 'success');
  }

  openNextDoor() {
    const cur = this.roomData.get(this.currentRoom);
    if (cur?.locked && !this.hasKey) {
      this.ui?.showNotification?.('🔒 Door is locked! You need a key.', 'danger');
      return false;
    }

    this.currentRoom++;
    this.hasKey = false;
    this.gold += Math.floor(Math.random() * 15) + 5;
    this.ui?.showNotification?.(`🚪 Opened Door ${this.currentRoom}!`, 'success');

    if (this.currentRoom >= this.maxRooms) {
      this.state = 'ENDED';
      this.ui?.showNotification?.('🎉 YOU ESCAPED THE HOTEL (Room 100)!', 'success');
    } else {
      this.generateRoom(this.currentRoom);
    }
    return true;
  }

  getHudData() {
    return {
      mode: 'Doors',
      state: this.state,
      door: this.currentRoom,
      gold: this.gold,
      hasKey: this.hasKey,
      isHiding: this.isHidingInCloset,
      flicker: this.lightsFlickering,
      rush: this.rushActive,
      battery: Math.round(this.flashlightBattery),
    };
  }
}
