/**
 * Voxel.io Bedwars Game Mode
 * Complete 4-team Bedwars with base generators, diamond/emerald islands, shop, beds, and bot AI.
 */

import { GameModeBase } from './GameModeBase.js';

export class BedwarsMode extends GameModeBase {
  constructor(options = {}) {
    super('bedwars', 'Bedwars', options);

    this.teams = {
      red: { name: 'Red', color: '#ff4444', bedAlive: true, spawn: [0, 65, -40], players: [] },
      blue: { name: 'Blue', color: '#4488ff', bedAlive: true, spawn: [0, 65, 40], players: [] },
      green: { name: 'Green', color: '#44cc44', bedAlive: true, spawn: [-40, 65, 0], players: [] },
      yellow: { name: 'Yellow', color: '#ffcc00', bedAlive: true, spawn: [40, 65, 0], players: [] },
    };

    this.generators = [
      // Base generators (iron/gold)
      { type: 'iron', pos: [0, 64, -38], interval: 2.0, timer: 0 },
      { type: 'gold', pos: [0, 64, -38], interval: 6.0, timer: 0 },
      { type: 'iron', pos: [0, 64, 38], interval: 2.0, timer: 0 },
      { type: 'gold', pos: [0, 64, 38], interval: 6.0, timer: 0 },
      { type: 'iron', pos: [-38, 64, 0], interval: 2.0, timer: 0 },
      { type: 'gold', pos: [-38, 64, 0], interval: 6.0, timer: 0 },
      { type: 'iron', pos: [38, 64, 0], interval: 2.0, timer: 0 },
      { type: 'gold', pos: [38, 64, 0], interval: 6.0, timer: 0 },
      // Diamond generators
      { type: 'diamond', pos: [-25, 64, -25], interval: 15.0, timer: 0 },
      { type: 'diamond', pos: [25, 64, 25], interval: 15.0, timer: 0 },
      // Emerald generator (Middle)
      { type: 'emerald', pos: [0, 66, 0], interval: 25.0, timer: 0 },
    ];

    this.localTeam = options.team || 'red';
    this.scores = { red: 0, blue: 0, green: 0, yellow: 0 };
    this.shopItems = [
      { id: 'wool', name: 'Wool x16', cost: 4, currency: 'iron', blockType: 35 },
      { id: 'oak_wood', name: 'Wood Planks x16', cost: 4, currency: 'gold', blockType: 5 },
      { id: 'stone_sword', name: 'Stone Sword', cost: 10, currency: 'iron', damage: 5 },
      { id: 'iron_sword', name: 'Iron Sword', cost: 7, currency: 'gold', damage: 6 },
      { id: 'diamond_sword', name: 'Diamond Sword', cost: 4, currency: 'emerald', damage: 7 },
      { id: 'bow', name: 'Bow + 16 Arrows', cost: 12, currency: 'gold' },
      { id: 'golden_apple', name: 'Golden Apple', cost: 3, currency: 'gold', heal: 10 },
      { id: 'obsidian', name: 'Obsidian x4', cost: 4, currency: 'emerald', blockType: 49 },
    ];
  }

  onStart() {
    this.teams[this.localTeam].players.push('local_player');

    // Generate bedwars map islands if engine has world
    if (this.engine?.world) {
      this.generateBedwarsMap();
    }

    // Spawn AI bots for remaining teams if offline or requested
    const botTeams = ['blue', 'green', 'yellow'];
    for (const teamKey of botTeams) {
      const bot = {
        id: `bot_${teamKey}`,
        name: `${this.teams[teamKey].name}Bot`,
        team: teamKey,
        pos: [...this.teams[teamKey].spawn],
        hp: 20,
        resources: { iron: 0, gold: 0, diamond: 0, emerald: 0 },
        actionState: 'GATHER', // 'GATHER' | 'BRIDGE' | 'ATTACK' | 'DEFEND'
        target: null,
      };
      this.bots.push(bot);
      this.teams[teamKey].players.push(bot.id);
    }
  }

  generateBedwarsMap() {
    const world = this.engine.world;
    if (!world?.setBlock) return;

    // Center Island (11x11 platform at y=65)
    for (let x = -5; x <= 5; x++) {
      for (let z = -5; z <= 5; z++) {
        world.setBlock(x, 65, z, 1); // stone
        world.setBlock(x, 66, z, 2); // grass
      }
    }

    // 4 Team Islands
    const teamOffsets = [
      [0, -40], // Red
      [0, 40],  // Blue
      [-40, 0], // Green
      [40, 0],  // Yellow
    ];

    teamOffsets.forEach(([cx, cz], idx) => {
      for (let x = cx - 6; x <= cx + 6; x++) {
        for (let z = cz - 6; z <= cz + 6; z++) {
          world.setBlock(x, 63, z, 1);
          world.setBlock(x, 64, z, 2);
        }
      }
      // Bed block marker
      world.setBlock(cx, 65, cz, 35); // Bed wool marker
    });
  }

  onUpdate(dt) {
    // Tick generators
    for (const gen of this.generators) {
      gen.timer += dt;
      if (gen.timer >= gen.interval) {
        gen.timer = 0;
        this.emitResourceDrop(gen);
      }
    }

    // Tick AI Bots
    for (const bot of this.bots) {
      this.updateBot(bot, dt);
    }
  }

  emitResourceDrop(gen) {
    if (this.engine?.localPlayer) {
      const [gx, gy, gz] = gen.pos;
      const [px, py, pz] = this.engine.localPlayer.position || [0, 65, -40];
      const dist = Math.hypot(px - gx, py - gy, pz - gz);
      if (dist < 3.5) {
        this.engine.localPlayer.addInventory?.(gen.type, 1);
      }
    }
  }

  updateBot(bot, dt) {
    if (!this.teams[bot.team].bedAlive && bot.hp <= 0) return;

    // Simple FSM bot logic
    if (bot.actionState === 'GATHER') {
      bot.resources.iron += dt * 0.5;
      bot.resources.gold += dt * 0.15;
      if (bot.resources.iron >= 16) {
        bot.actionState = 'BRIDGE';
      }
    } else if (bot.actionState === 'BRIDGE') {
      // Bridge towards center [0, 65, 0]
      const [bx, by, bz] = bot.pos;
      const dirX = 0 - bx;
      const dirZ = 0 - bz;
      const len = Math.hypot(dirX, dirZ);
      if (len > 3) {
        bot.pos[0] += (dirX / len) * 3.5 * dt;
        bot.pos[2] += (dirZ / len) * 3.5 * dt;
        // Place bridge block in world
        const ix = Math.floor(bot.pos[0]);
        const iz = Math.floor(bot.pos[2]);
        this.engine?.world?.setBlock?.(ix, 64, iz, 35);
      } else {
        bot.actionState = 'ATTACK';
      }
    } else if (bot.actionState === 'ATTACK') {
      // Target enemy bed (e.g. Red if bot is Blue)
      const targetTeam = bot.team === 'red' ? 'blue' : 'red';
      const bedPos = this.teams[targetTeam].spawn;
      const [bx, by, bz] = bot.pos;
      const dist = Math.hypot(bedPos[0] - bx, bedPos[2] - bz);
      if (dist < 4) {
        // Attack Bed
        if (this.teams[targetTeam].bedAlive) {
          this.destroyBed(targetTeam, bot.id);
        }
      }
    }
  }

  destroyBed(teamKey, breakerId) {
    if (!this.teams[teamKey].bedAlive) return;
    this.teams[teamKey].bedAlive = false;
    const msg = `Bed of Team ${this.teams[teamKey].name} was DESTROYED by ${breakerId}!`;
    console.log(`[Voxel.io Bedwars] ${msg}`);
    this.ui?.showNotification?.(msg, 'warning');
    this.net?.broadcast?.({
      type: 'BED_DESTROYED',
      payload: { team: teamKey, breakerId },
    });
  }

  onPlayerAttack(attackerId, targetId, weapon) {
    const damage = weapon?.damage || 4;
    console.log(`[Bedwars] ${attackerId} hit ${targetId} for ${damage} dmg`);
    return { damage, knockback: [0, 2, 4] };
  }

  getHudData() {
    return {
      mode: 'Bedwars',
      state: this.state,
      localTeam: this.localTeam,
      teams: {
        red: { alive: this.teams.red.bedAlive, name: 'Red' },
        blue: { alive: this.teams.blue.bedAlive, name: 'Blue' },
        green: { alive: this.teams.green.bedAlive, name: 'Green' },
        yellow: { alive: this.teams.yellow.bedAlive, name: 'Yellow' },
      },
      time: Math.floor(this.elapsedTime),
      bots: this.bots.length,
    };
  }
}
