/**
 * shared-net-offline/LocalGameLoop.js
 * Standalone Offline Match Controller for Voxel.io.
 * 
 * Provides:
 * - Deterministic local game loop (fixed 60 Hz tick) without any server connection
 * - AI Bot manager (spawning, ticking, difficulty configuration)
 * - Local event dispatcher for single-player practice & offline matches
 */

export class LocalGameLoop {
  /**
   * @param {Object} gameInstance Reference to game/world/physics instance
   * @param {Object} [options={}]
   */
  constructor(gameInstance, options = {}) {
    this.game = gameInstance;
    this.isRunning = false;
    this.tickRate = options.tickRate || 60;
    this.tickInterval = 1000 / this.tickRate;
    this.lastTime = 0;
    this.timerId = null;
    this.bots = [];
    this.isOffline = true;
  }

  /**
   * Spawns an AI bot into the local offline match.
   * @param {Object} botConfig
   */
  spawnBot(botConfig = {}) {
    const bot = {
      id: 'bot_' + (this.bots.length + 1),
      name: botConfig.name || `VoxelBot-${this.bots.length + 1}`,
      team: botConfig.team || 'red',
      position: { x: botConfig.x || 0, y: botConfig.y || 22, z: botConfig.z || 0 },
      health: botConfig.health || 100,
      brain: botConfig.brain || null,
      isBot: true,
    };

    this.bots.push(bot);
    if (this.game && typeof this.game.onBotSpawned === 'function') {
      this.game.onBotSpawned(bot);
    }
    return bot;
  }

  /**
   * Starts the offline tick loop.
   */
  start() {
    if (this.isRunning) return;
    this.isRunning = true;
    this.lastTime = performance.now();

    const loop = (now) => {
      if (!this.isRunning) return;
      const dt = Math.min((now - this.lastTime) / 1000, 0.1); // clamp delta
      this.lastTime = now;

      this.tick(dt);

      if (typeof requestAnimationFrame !== 'undefined') {
        this.timerId = requestAnimationFrame(loop);
      } else {
        this.timerId = setTimeout(() => loop(performance.now()), this.tickInterval);
      }
    };

    if (typeof requestAnimationFrame !== 'undefined') {
      this.timerId = requestAnimationFrame(loop);
    } else {
      this.timerId = setTimeout(() => loop(performance.now()), this.tickInterval);
    }
  }

  /**
   * Advances one simulation step.
   * @param {number} dt Delta time in seconds
   */
  tick(dt) {
    // 1. Tick bots
    for (const bot of this.bots) {
      if (bot.brain && typeof bot.brain.update === 'function') {
        bot.brain.update(dt, this.game);
      }
    }

    // 2. Tick local game instance if present
    if (this.game && typeof this.game.updatePhysics === 'function') {
      this.game.updatePhysics(dt);
    }
  }

  /**
   * Stops the offline loop.
   */
  stop() {
    this.isRunning = false;
    if (typeof cancelAnimationFrame !== 'undefined' && this.timerId) {
      cancelAnimationFrame(this.timerId);
    } else if (this.timerId) {
      clearTimeout(this.timerId);
    }
    this.timerId = null;
  }

  /**
   * Cleans up bots and match state.
   */
  reset() {
    this.stop();
    this.bots = [];
  }
}
